+ * Returns null for an unterminated quote: that command is not parseable, and is never guessed at.
+ */
+export function splitHookCommand(cmd: string): string[] | null {
+  const words: string[] = [];
+  let cur = "";
+  let inWord = false;
+  let quote: '"' | "'" | null = null;
+  for (let i = 0; i < cmd.length; i++) {
+    const c = cmd[i]!;
