+      if (c === quote) quote = null;
+      else if (quote === '"' && c === "\\" && cmd[i + 1] === '"') {
+        cur += '"';
+        i++;
+      } else cur += c;
+      continue;
+    }
+    if (c === '"' || c === "'") {
+      quote = c;
+      inWord = true;
+      continue;
+    }
+    if (/\s/.test(c)) {
+      if (inWord) words.push(cur);
+      cur = "";
+      inWord = false;
+      continue;
+    }
+    cur += c;
+    inWord = true;
+  }
+  if (quote) return null;
+  if (inWord) words.push(cur);
+  return words;
